package com.bank.recon;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SetZeroesDemo {

    private static final Logger log = Logger.getLogger(SetZeroesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Rows are dates, columns are branches. A zero means a discrepancy.
        int[][] grid = {
                {12000, 15000, 0, 30000},
                {41000, 50000, 58000, 63000},
                {71000, 0, 90000, 99000}
        };

        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        log.info(() -> priya.getHolderName() + " filing reconciliation; grid before quarantine:");
        for (int[] row : grid) {
            log.info(() -> Arrays.toString(row));
        }

        ReconciliationGrid recon = new ReconciliationGrid();
        recon.quarantineZeroes(grid);

        log.info("Grid after quarantine:");
        for (int[] row : grid) {
            log.info(() -> Arrays.toString(row));
        }
    }
}

