class ReconciliationGrid {

    private static final Logger log = Logger.getLogger(ReconciliationGrid.class.getName());

    // Zeroes the full row and column of any zero cell, in place, O(1) extra space.
    void quarantineZeroes(int[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return;
        }
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Step 1: remember if first row / first column originally held a zero.
        boolean firstRowHasZero = false;
        boolean firstColHasZero = false;
        for (int j = 0; j < cols; j++) {
                if (matrix[0][j] == 0) { firstRowHasZero = true;
                break; }
        }
        for (int i = 0; i < rows; i++) {
                if (matrix[i][0] == 0) { firstColHasZero = true;
                break; }
        }

        // Step 2: use first row & column as markers for the inner matrix.
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;   // mark the row
                    matrix[0][j] = 0;   // mark the column
                }
            }
        }
        log.fine("markers written into first row and first column");

        // Step 3: zero inner cells based on markers.
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) {
                    matrix[i][j] = 0;
                }
            }
        }

        // Step 4: apply the saved flags to first row and first column.
        if (firstRowHasZero) {
            for (int j = 0; j < cols; j++) matrix[0][j] = 0;
        }
        if (firstColHasZero) {
            for (int i = 0; i < rows; i++) matrix[i][0] = 0;
        }
        log.info("quarantine complete");
    }
}

